<?php require __DIR__.'/ui.php';role(['admin','gerente','producao']);$p=db();if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$p->prepare("INSERT INTO production_capacity(work_date,max_orders,max_minutes,notes)VALUES(?,?,?,?) ON CONFLICT(work_date) DO UPDATE SET max_orders=excluded.max_orders,max_minutes=excluded.max_minutes,notes=excluded.notes")->execute([$_POST['work_date'],$_POST['max_orders'],$_POST['max_minutes'],$_POST['notes']]);go('capacity.php');}$rows=$p->query("SELECT pc.*, (SELECT COUNT(*) FROM orders o WHERE date(o.delivery_date)=pc.work_date) booked FROM production_capacity pc ORDER BY work_date")->fetchAll();page_head('Capacidade de produção');?><div class="grid g2"><div class="card"><h2>Capacidade por dia</h2><form method="post"><?=csrf_field()?><label>Data</label><input type="date" name="work_date" required><label>Máximo de pedidos</label><input type="number" name="max_orders" value="<?=e(setting('default_daily_capacity','12'))?>"><label>Minutos disponíveis</label><input type="number" name="max_minutes" value="480"><label>Notas</label><textarea name="notes"></textarea><button class="primary">Salvar</button></form></div><div class="card"><table><tr><th>Data</th><th>Capacidade</th><th>Reservados</th><th>Situação</th></tr><?php foreach($rows as $x):?><tr><td><?=$x['work_date']?></td><td><?=$x['max_orders']?></td><td><?=$x['booked']?></td><td><?=$x['booked']>$x['max_orders']?'⚠️ Sobrecarga':'✓ OK'?></td></tr><?php endforeach;?></table></div></div><?php page_foot();?>